<?php $pageTitle='Car Details'; require_once __DIR__ . '/../includes/header.php'; $id=isset($_GET['id'])?(int)$_GET['id']:0; $car=find_car($id); if(!$car){ set_flash('danger','Car not found.'); redirect('/car-rent-sale-system/index.php'); } ?><div class="container py-5"><div class="row g-4"><div class="col-lg-6"><img class="img-fluid rounded-4 shadow-sm" src="<?= e($car['image']); ?>" alt="car"></div><div class="col-lg-6"><h1><?= e($car['title']); ?></h1><p class="lead text-muted"><?= e($car['brand']); ?> <?= e($car['model']); ?> - <?= e($car['year']); ?></p><div class="row row-cols-2 g-3 mb-3"><div><strong>Fuel:</strong> <?= e($car['fuel_type']); ?></div><div><strong>Transmission:</strong> <?= e($car['transmission']); ?></div><div><strong>Seats:</strong> <?= e($car['seats']); ?></div><div><strong>Mileage:</strong> <?= e($car['mileage']); ?> km</div></div><p><?= e($car['description']); ?></p><?php if(in_array($car['car_type'], ['rental','both'], true)): ?><p class="price-tag">Rental: $<?= e(number_format((float)$car['rental_price_per_day'],2)); ?>/day</p><a class="btn btn-primary me-2" href="/car-rent-sale-system/pages/booking.php?car_id=<?= (int)$car['id']; ?>">Rent Now</a><?php endif; ?><?php if(in_array($car['car_type'], ['sale','both'], true)): ?><p class="price-tag">Sale: $<?= e(number_format((float)$car['sale_price'],2)); ?></p><a class="btn btn-warning" href="/car-rent-sale-system/pages/inquiry.php?car_id=<?= (int)$car['id']; ?>">Buy Now</a><?php endif; ?></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
